"""PayPal Orders v2 through PayPal's official Python server SDK (`paypal-server-sdk`, generated by APIMatic).

The SDK is synchronous, so each call runs in a worker thread. This module is the only place that touches it; the rest of
the app sees plain dicts and `PaymentError`, which also makes the gateway easy to replace in tests.
"""
from __future__ import annotations

import asyncio
import logging
from typing import Any

from paypalserversdk.configuration import Environment
from paypalserversdk.exceptions.api_exception import ApiException
from paypalserversdk.http.auth.o_auth_2 import ClientCredentialsAuthCredentials
from paypalserversdk.models.amount_with_breakdown import AmountWithBreakdown
from paypalserversdk.models.checkout_payment_intent import CheckoutPaymentIntent
from paypalserversdk.models.order_request import OrderRequest
from paypalserversdk.models.payment_source import PaymentSource
from paypalserversdk.models.paypal_wallet import PaypalWallet
from paypalserversdk.models.paypal_wallet_experience_context import PaypalWalletExperienceContext
from paypalserversdk.models.purchase_unit_request import PurchaseUnitRequest
from paypalserversdk.paypal_serversdk_client import PaypalServersdkClient

from ..core.config import CreditPack, Settings

logger = logging.getLogger("proofbeforepay.paypal")


class PaymentError(RuntimeError):
    """A PayPal call failed. The message is safe to show the user."""


def _value(enum_or_str: Any) -> str:
    return str(getattr(enum_or_str, "value", enum_or_str) or "")


class PayPalGateway:
    def __init__(self, settings: Settings) -> None:
        self.settings = settings
        self._client: PaypalServersdkClient | None = None

    @property
    def orders(self) -> Any:
        if self._client is None:
            self._client = PaypalServersdkClient(
                client_credentials_auth_credentials=ClientCredentialsAuthCredentials(
                    o_auth_client_id=self.settings.paypal_client_id, o_auth_client_secret=self.settings.paypal_client_secret
                ),
                environment=Environment.PRODUCTION if self.settings.paypal_env == "live" else Environment.SANDBOX,
            )
        return self._client.orders

    async def create_order(self, pack: CreditPack, *, reference: str, return_url: str, cancel_url: str) -> dict[str, str]:
        """Create a checkout order for a pack. `reference` (our own order id) is echoed back by PayPal on capture."""
        body = OrderRequest(
            intent=CheckoutPaymentIntent.CAPTURE,
            purchase_units=[
                PurchaseUnitRequest(
                    reference_id=pack.id,
                    custom_id=reference,
                    description=f"{pack.credits} ProofBeforePay credits ({pack.label})",
                    amount=AmountWithBreakdown(currency_code=self.settings.paypal_currency, value=pack.price),
                )
            ],
            payment_source=PaymentSource(
                paypal=PaypalWallet(
                    experience_context=PaypalWalletExperienceContext(
                        brand_name="ProofBeforePay",
                        shipping_preference="NO_SHIPPING",  # digital goods
                        user_action="PAY_NOW",
                        return_url=return_url,
                        cancel_url=cancel_url,
                    )
                )
            ),
        )
        # Our order id doubles as PayPal's idempotency key, so a retried request can't create a second order.
        response = await self._call(self.orders.create_order, {"body": body, "prefer": "return=representation", "paypal_request_id": reference})
        order = response.body
        links = {_value(link.rel): link.href for link in (order.links or [])}
        approve = links.get("payer-action") or links.get("approve")
        if not order.id or not approve:
            raise PaymentError("PayPal didn't return a checkout link. Please try again.")
        return {"id": order.id, "approve_url": approve, "status": _value(order.status)}

    async def capture_order(self, order_id: str, *, request_id: str) -> dict[str, str]:
        """Capture an approved order. Returns the facts the caller must verify before granting credits."""
        response = await self._call(self.orders.capture_order, {"id": order_id, "prefer": "return=representation", "paypal_request_id": request_id})
        order = response.body
        unit = (order.purchase_units or [None])[0]
        captures = ((unit.payments.captures if unit and unit.payments else None) or [])
        capture = captures[0] if captures else None
        return {
            "order_status": _value(order.status),
            "capture_status": _value(capture.status) if capture else "",
            "capture_id": (capture.id if capture else "") or "",
            "amount": (capture.amount.value if capture and capture.amount else "") or "",
            "currency": (capture.amount.currency_code if capture and capture.amount else "") or "",
            "custom_id": (unit.custom_id if unit else "") or "",
            "payer_email": (order.payer.email_address if order.payer else "") or "",
        }

    async def _call(self, fn: Any, options: dict[str, Any]) -> Any:
        try:
            return await asyncio.to_thread(fn, options)
        except ApiException as exc:
            logger.warning("PayPal call failed: %s %s", getattr(exc, "response_code", ""), exc)
            raise PaymentError("PayPal couldn't complete that request. No money was taken. Please try again.") from exc
        except Exception as exc:  # network errors, auth failures: never leak details to the browser
            logger.warning("PayPal call crashed: %s", exc)
            raise PaymentError("Couldn't reach PayPal. Please try again in a moment.") from exc
